def parse_json(s: str) -> object:
    """A recursive descent parser for JSON strings."""

    index = 0

    def next_token():
        nonlocal index
        while index < len(s) and s[index].isspace():
            index += 1
        if index == len(s):
            return None
        char = s[index]
        if char in '{[]},"':
            index += 1
            return char
        elif char.isdigit() or (char == '-' and s[index + 1].isdigit()):
            start = index
            if char == '-':
                index += 1
            while index < len(s) and (s[index].isdigit() or s[index] == '.'):
                index += 1
            return s[start:index]
        elif char == 't':
            index += 4
            return True
        elif char == 'f':
            index += 5
            return False
        elif char == 'n':
            index += 4
            return None
        elif char == '"':
            start = index + 1
            while True:
                index = s.find('"', start)
                if index == -1:
                    raise ValueError("Unterminated string")
                if s[index - 1] != '\\':
                    break
                start = index + 1
            result = s[start - 1:index].replace('\\"', '"').replace('\\\\', '\\')
            index += 1
            return result
        return None

    def parse_value():
        token = next_token()
        if token is None:
            raise ValueError("Unexpected end of input")
        if isinstance(token, str) and token[0] == '"':
            return token
        if token in {'{', '['}:
            return parse_object() if token == '{' else parse_array()
        if token in {'}', ']'}:
            raise ValueError("Unexpected closing brace")
        if token in {'true', 'false', 'null'}:
            return token
        if token.replace('.', '', 1).isdigit() or (token[0] == '-' and token[1:].replace('.', '', 1).isdigit()):
            return float(token) if '.' in token else int(token)
        raise ValueError(f"Unexpected token: {token}")

    def parse_object():
        obj = {}
        while True:
            token = next_token()
            if token == '}':
                return obj
            if not isinstance(token, str) or token[0] != '"':
                raise ValueError("Expected string as key")
            key = token
            if next_token() != ':':
                raise ValueError("Expected colon after key")
            obj[key] = parse_value()
            token = next_token()
            if token == '}':
                return obj
            if token != ',':
                raise ValueError("Expected comma or closing brace")

    def parse_array():
        arr = []
        while True:
            token = next_token()
            if token == ']':
                return arr
            index -= 1  # Put back the token
            arr.append(parse_value())
            token = next_token()
            if token == ']':
                return arr
            if token != ',':
                raise ValueError("Expected comma or closing bracket")

    result = parse_value()
    if next_token() is not None:
        raise ValueError("Extra data after valid JSON")
    return result

